Full code to reproduce this:
```
import { TextField } from '@mui/material';
import { useState } from 'react';

export default function App() {
  const [inputs, setInputs] = useState({
    user: {
      value: '',
      helperText: 'At least three characters',
      helperTextKey: 0,
      isError: true,
    },
  });
  return (
    <TextField
      required
      name="user"
      id="user"
      label="User"
      defaultValue={inputs.user.value}
      onChange={(e) => {
        setInputs((prev) => ({
          ...prev,
          user: {
            value: e.target.value,
            helperText: 'At least three characters',
            helperTextKey: Math.random(),
            isError: e.target.value.length < 3,
          },
        }));
      }}
      error={inputs.user.isError}
      helperText={inputs.user.helperText}
      slotProps={{
        formHelperText: {
          'aria-live': 'assertive',
          key: inputs.user.helperTextKey,
        },
        inputLabel: { 'aria-hidden': true },
        input: {
          inputProps: { 'aria-label': 'User' },
        },
      }}
    ></TextField>
  );
}
```

### Current behavior

The following error appears in the dev tools console:

```
react_jsx-runtime.js?v=8f5e45b7:161
