The solution is to use a custom FormHelperText component in `slots.formHelperText`: https://stackblitz.com/edit/github-yvtmqcbt-ttlv6y56?file=src%2FApp.tsx
```tsx
import * as React from 'react';
import TextField from '@mui/material/TextField';
import FormHelperText, {
  FormHelperTextProps,
} from '@mui/material/FormHelperText';

declare module '@mui/material/TextField' {
  interface TextFieldFormHelperTextSlotPropsOverrides {
    helperTextKey?: React.Key;
  }
}

const LiveFormHelperText = React.forwardRef<
  HTMLParagraphElement,
  FormHelperTextProps & { helperTextKey?: React.Key }
>(function LiveFormHelperText(props, ref) {
  const { helperTextKey, children, ...other } = props;

  return (
    <FormHelperText ref={ref} key={helperTextKey} {...other}>
      {children}
    </FormHelperText>
  );
});

export default function App() {
  const [inputs, setInputs] = React.useState({
    user: {
      value: '',
      helperText: 'At least three characters',
      helperTextKey: 0,
      isError: true,
    },
  });

  return (
    <TextField
      required
      name="user"
      id="user"
      label="User"
      defaultValue={inputs.user.value}
      onChange={(e) => {
        setInputs((prev) => ({
          ...prev,
          user: {
            value: e.target.value,
            helperText: 'At least three characters',
            helperTextKey: Math.random(),
            isError: e.target.value.length < 3,
          },
        }));
      }}
      error={inputs.user.isError}
      helperText={inputs.user.helperText}
      slots={{
        formHelperText: LiveFormHelperText,
      }}
      slotProps={{
        formHelperText: {
          helperTextKey: inputs.user.helperTextKey,
          'aria-live': 'assertive',
        },
      }}
    />
  );
}
```

With this, the warning is not shown. 

