@chkp-elinak In your sandbox you also need to use the `autoWidth` prop, but even with that there is a bug; in the mean time you can use a ref and ResizeObserver to "sync" the width as a workaround:

```jsx
const anchorRef = React.useRef(null);
const [width, setWidth] = React.useState<number | undefined>();

React.useEffect(() => {
  const anchorEl = anchorRef.current;
  if (!anchorEl) {
    return;
  }

  const observer = new ResizeObserver(([entry]) => {
    if (entry.contentRect.width) {
      setWidth(entry.contentRect.width);
    }
  });

  observer.observe(anchorEl);
  return () => observer.disconnect();
}, []);

<Select
  ref={anchorRef}
  fullWidth
  autoWidth
  MenuProps={{
    slotProps: {
      paper: {
        style: {
          minWidth: 120,
          width: width ?? undefined,
        },
      },
    },
  }}
/>
```

